import {t as uiText,receiptLogo,language} from "./i18n.js";
import {snapshotWeeklyReceipt} from './receipt-snapshot.js';
import {drawReceiptSummary,drawHarvestTile} from './receipt-canvas.js';
import {PLANTS,growth as legacyGrowth,elapsed,total,localDay,completeTask,clock,plantFor as legacyPlantFor} from './farm.js';
import {sprite as pixelSprite} from './pixels.js';
import {queueGrowth,historyNames,groupedHarvest,settleHarvest} from './collections.js';
import {installUpgrades} from './upgrades.js';
import {installAppearance} from './appearance.js';
import {MUSHROOMS} from './assets/mushrooms.js';
import {LOGS,STUMP_SLOTS} from './stump-layout.js';
import {activityRows} from './receipt.js';
import {weekSummary} from './weekly.js';
import {stumpProgress,harvestMushrooms,mushroomGroups,mushroomAt} from './mushroom-logic.js';
const $=id=>document.getElementById(id),KEY='daybook-mushrooms-v1',uid=()=>globalThis.crypto?.randomUUID?.()||String(Date.now())+Math.random();
const seed=()=>({version:1,tasks:[],sessions:[],claimed:[],active:null});
let bookPayload=null;
let state=seed(),lastIndex=-1,lastStage=-1,appearance=null;
try{const saved=JSON.parse(localStorage.getItem(KEY));if(saved?.version===1&&Array.isArray(saved.tasks)&&Array.isArray(saved.sessions)&&Array.isArray(saved.claimed))state=saved;}catch{}
state.favorites??=[];state.taskNames??=[];state.hiddenNames??=[];state.cropDefs??=[];state.cropAssets??={};state.builtinSettings??={};state.harvests??=[];state.cropFruits??={};state.shelf??=state.claimed.slice(0,6).map(index=>({index,pot:null}));while(state.shelf.length<6)state.shelf.push(null);
if(!state.cropQueue){const count=legacyGrowth(total(state)).completed;state.cropQueue=Array.from({length:count+1},(_,i)=>legacyPlantFor(i));}
function initializeStump(){if(state.stump)state.stump.pendingSeconds??=0;if(!state.stump){state.stump={version:1,carrySeconds:0,nextSerial:0,seed:Math.floor(Math.random()*1000000),harvests:[]};if(state.active)state.active.mushroomBase=elapsed(state.active);}}
initializeStump();state.stump.pendingSeconds??=0;
function activeGrowthSeconds(){return state.active?Math.max(0,elapsed(state.active)-(state.active.mushroomBase||0)):0;}
function stumpInfo(){return stumpProgress(state.stump,activeGrowthSeconds());}
let matureTimeout=null,matureKey=-1;
function makeCrop(index){const choices=PLANTS.map((p,i)=>({...p,...(state.builtinSettings[i]||{}),base:i})).filter(p=>p.enabled!==false).concat(state.cropDefs.filter(p=>p.enabled!==false));const list=choices.length?choices:PLANTS;let p=list[index%list.length];if(state.nextCropKey){const chosen=choices.find(c=>c.assetKey===state.nextCropKey||'builtin:'+c.base===state.nextCropKey);if(chosen)p=chosen;state.nextCropKey=null;}return {...p,pot:((p.pot||0)+Math.floor(index/list.length))%3,variant:Math.floor(index/list.length)%3};}
function growth(seconds){const g=queueGrowth(seconds,state.cropQueue,makeCrop);if(g.added)save();return g;}
function plantFor(index){growth(total(state));const p=state.cropQueue[index]||legacyPlantFor(index);return{...p,images:p.assetKey?state.cropAssets[p.assetKey]:p.images,fruitAsset:p.assetKey?state.cropFruits[p.assetKey]:p.fruitAsset};}
function sprite(p,stage=4,variant=0){return p.images?.[stage]||pixelSprite(p,stage,variant);}
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));$('status').dataset.error='';return true;}catch{$('status').dataset.error='true';$('status').textContent=uiText("瀏覽器無法儲存資料，請保留此頁面。");return false;}}
function say(msg){if(!$('status').dataset.error)$('status').textContent=msg;}
const mins=s=>{const m=Math.floor(Math.max(0,s)/60);return m>=60?Math.floor(m/60)+uiText(" 小時 ")+(m%60)+uiText(" 分鐘"):m+uiText(" 分鐘");};
const stages=[uiText("種子"),uiText("嫩芽"),uiText("葉叢"),uiText("花苞"),uiText("成熟")];
function phaseNames(p){return p.phases||stages;}
function fruitSprite(p){return p.fruit||p.fruitAsset||(p.images?.at(-1))||sprite(p,4,p.variant);}
function pendingIndices(g){return Array.from({length:g.completed},(_,i)=>i).filter(i=>!state.claimed.includes(i));}

function currentDay(){return $('taskDay').value||localDay();}
function done(t,day){return t.done.includes(t.kind==='daily'?day:'done');}
function tasksFor(day){return state.tasks.filter(t=>t.kind==='daily'?t.day<=day:t.day===day);}
function renderManualTasks(){const list=$('manualTasks');list.replaceChildren();for(const t of tasksFor(currentDay())){const button=document.createElement('button');button.type='button';button.textContent=t.text;button.className='manualTaskChoice'+($('manualName').value===t.text?' picked':'');button.setAttribute('aria-pressed',String($('manualName').value===t.text));button.onclick=()=>{$('manualName').value=t.text;renderManualTasks();};list.append(button);}}
function renderPicker(){renderManualTasks();renderShortcuts();const selected=$('target').value;$('target').replaceChildren(new Option(uiText("自由記錄（不連結待辦）"),''));for(const t of tasksFor(currentDay()).filter(t=>!done(t,currentDay()))){$('target').add(new Option((t.kind==='daily'?uiText("每日 · "):'')+t.text,t.id));}if([...$('target').options].some(o=>o.value===selected))$('target').value=selected;$('freeName').hidden=!!$('target').value;}
function renderTasks(){const list=$('tasks');list.replaceChildren();for(const kind of ['once','daily']){const group=document.createElement('div');group.className='taskGroup '+(kind==='daily'?'daily':'');const h=document.createElement('h3');h.textContent=kind==='daily'?uiText("每日固定"):uiText("一次性待辦");group.append(h);const items=tasksFor(currentDay()).filter(t=>t.kind===kind);if(!items.length){const empty=document.createElement('p');empty.className='muted';empty.textContent=uiText("還沒有項目");group.append(empty);}for(const t of items){const row=document.createElement('div');row.className='taskRow '+(done(t,currentDay())?'completed':'');const label=document.createElement('label'),check=document.createElement('input'),name=document.createElement('span');check.type='checkbox';check.checked=done(t,currentDay());check.onchange=()=>{const k=t.kind==='daily'?currentDay():'done';t.done=check.checked?[...new Set([...t.done,k])]:t.done.filter(d=>d!==k);sendBook('toggle-task',{id:t.id,day:currentDay(),done:check.checked});save();renderTasks();renderPicker();};name.textContent=t.text;label.append(check,name);const play=document.createElement('button');play.textContent='▶';play.setAttribute('aria-label',uiText("計時 ")+t.text);play.disabled=!!state.active;play.onclick=()=>start(t.id);const rem=document.createElement('button');rem.textContent='×';rem.className='remove';rem.setAttribute('aria-label',uiText("刪除 ")+t.text);rem.disabled=state.active?.taskId===t.id;rem.onclick=()=>{if(confirm(uiText("刪除這個示範待辦？"))){state.taskNames=[...new Set([...state.taskNames,t.text])];state.tasks=state.tasks.filter(x=>x.id!==t.id);sendBook('delete-task',{id:t.id});save();renderTasks();renderPicker();}};const star=document.createElement('button');star.textContent=state.favorites.includes(t.text)?'★':'☆';star.setAttribute('aria-label',uiText("收藏常用事項 ")+t.text);star.onclick=()=>{sendBook('favorite',{name:t.text});state.favorites=state.favorites.includes(t.text)?state.favorites.filter(n=>n!==t.text):[...state.favorites,t.text];save();renderTasks();renderShortcuts();};row.append(label,star,play,rem);group.append(row);}list.append(group);}}
function start(id=$('target').value){if(state.active)return;const task=state.tasks.find(t=>t.id===id);state.active={id:uid(),taskId:task?.id||null,name:task?.text||$('freeName').value.trim()||uiText("自由記錄"),day:currentDay(),seconds:0,since:Date.now(),mushroomBase:0};save();say(uiText("正在安靜記錄，樹樁會慢慢長菇。"));renderTimer();renderTasks();tick();}
function pauseResume(){if(!state.active){start();return;}if(state.active.since===null){state.active.since=Date.now();say(uiText("繼續記錄。"));}else{state.active.seconds=elapsed(state.active);state.active.since=null;say(uiText("已暫停，蘑菇留在樹樁上。"));}save();renderTimer();tick();}
function finish(mark=false){const a=state.active;if(!a)return;const seconds=elapsed(a);state.stump.pendingSeconds=(state.stump.pendingSeconds||0)+Math.max(0,seconds-(a.mushroomBase||0));state.taskNames=[...new Set([...state.taskNames,a.name])];state.sessions.push({id:a.id,name:a.name,day:a.day,seconds,taskId:a.taskId,ended:Date.now(),source:a.source||'timer'});if(mark){state.tasks=completeTask(state.tasks,a);sendBook('complete',{id:a.taskId,day:a.day});}state.active=null;let picked=0;if($('finishHarvest').checked){const previous=state.stump.nextSerial;state.stump=harvestMushrooms(state.stump,0,a.id,localDay());picked=state.stump.nextSerial-previous;}save();say(uiText("留下 ")+mins(seconds)+(picked?uiText("，採收 ")+picked+uiText(" 朵。"):uiText("，小菇保留在樹樁上。"))+(mark?uiText("已勾選「")+a.name+'」。':''));$('reveal').hidden=!picked;$('reveal').textContent=uiText("這次採收 ")+picked+uiText(" 朵，已放入今日籃子。");renderTimer();renderTasks();renderPicker();tick();renderBook();}
function pickStump(){const p=stumpInfo();if(!p.count)return;const seconds=activeGrowthSeconds();if(state.active)state.active.mushroomBase=elapsed(state.active);state.stump=harvestMushrooms(state.stump,seconds,uid(),localDay());save();say(uiText("採收 ")+p.count+uiText(" 朵，已放進今日籃子。"));$('reveal').hidden=false;$('reveal').textContent=uiText("這次採收 ")+p.count+uiText(" 朵。");todaySignature='';tick();renderBook();}


function renderTimer(){const a=state.active;$('timerLabel').textContent=a?a.name+(a.since===null?uiText(" · 暫停中"):uiText(" · 記錄中")):uiText("選一件事，或直接開始");$('startBtn').textContent=a?(a.since===null?uiText("繼續記錄"):uiText("暫停")):uiText("開始記錄");$('finishBtn').hidden=!a;$('finishBtn').textContent=uiText("結束記錄");$('doneBtn').textContent=uiText("完成並打勾");$('doneBtn').hidden=!a?.taskId;$('adjustBtn').hidden=!a;$('taskPicker').hidden=!!a;$('timerBody').hidden=false;}
function renderGrowth(){const p=stumpInfo();$('readyBadge').textContent=p.count||'';$('stageTag').textContent=state.active?(state.active.since===null?uiText("保留中"):uiText("生長中")):uiText("等你開始");$('plantName').textContent=uiText("樹樁上可採收 × ")+p.count;$('plantBar').style.width=(p.ratio*100)+'%';$('plantProgress').textContent=uiText("下一朵已累積 ")+mins(p.partial)+uiText(" · 每累積 5 分鐘長一朵");$('harvestNow').hidden=false;$('harvestNow').disabled=!p.count;$('harvestNow').textContent=uiText("採收 ")+p.count+uiText(" 朵小菇");renderStump($('stumpShoots'),p);renderToday();}
function renderStump(target,p){target.replaceChildren();const count=Math.min(STUMP_SLOTS.length,p.count);const add=(i,m,partial=false)=>{const slot=STUMP_SLOTS[i],im=document.createElement('img');im.src=m.src;im.alt=m.label+(partial?uiText(" · 正在冒出"):uiText(" · 可採收"));im.className='stumpShoot'+(partial?' sprouting':'');im.style.left=slot.x+'%';im.style.top=slot.y+'%';im.style.zIndex=String(slot.row+2);im.dataset.row=String(slot.row);if(partial){im.style.transform='translate(-50%,-100%) scale('+(0.2+p.ratio*.8)+')';im.style.opacity=String(.35+p.ratio*.65);}target.append(im);};for(let i=0;i<count;i++)add(i,mushroomAt(state.stump,i));if(p.ratio>0&&count<STUMP_SLOTS.length)add(count,mushroomAt(state.stump,p.count),true);target.setAttribute('aria-label',uiText("上排九朵、下排六朵的小菇，樹樁上可採收 ")+p.count+uiText(" 朵"));}


let todaySignature='';
function renderMushrooms(target,batches){for(const group of mushroomGroups(batches)){const card=document.createElement('div');card.className='produce';const img=document.createElement('img');img.src=group.plant.src;img.alt=group.plant.label;const qty=document.createElement('strong');qty.className='quantity';qty.textContent='× '+group.count;const label=document.createElement('span');label.textContent=group.plant.label;card.append(img,qty,label);target.append(card);}}
function renderToday(){const batches=state.stump.harvests.filter(h=>h.day===localDay()),sig=localDay()+':'+batches.length+':'+state.stump.nextSerial;if(sig===todaySignature)return;todaySignature=sig;const count=batches.reduce((n,b)=>n+b.count,0),stage=count===0?0:count<12?1:2;$('basketArt').src='assets/basket-'+stage+'.png';$('basketArt').alt=[uiText("空的採菇籃"),uiText("有些收成的採菇籃"),uiText("滿滿收成的採菇籃")][stage];$('basketCount').textContent=uiText("今日 × ")+count;const duration=state.sessions.filter(s=>s.day===localDay()).reduce((n,s)=>n+s.seconds,0);$('checkGarden').title=uiText("今日 ")+mins(duration)+uiText(" · 採收 ")+count+uiText(" 朵");$('checkGarden').setAttribute('aria-label',uiText("展開今日採菇籃：")+mins(duration)+uiText("、")+count+uiText(" 朵"));$('todayHarvest').replaceChildren();renderMushrooms($('todayHarvest'),batches);if(!batches.some(b=>b.count))empty($('todayHarvest'),uiText("結束計時後，蘑菇會收進今日籃子。"));}

function renderProduce(target,indices,ready=false){for(const group of groupedHarvest(indices,plantFor)){const p=group.plant,card=document.createElement(ready?'button':'div');card.className='produce '+(ready?'ready':'');const im=document.createElement('img');im.src=ready?sprite(p,phaseNames(p).length-1,p.variant):fruitSprite(p);im.alt=p.name+(ready?uiText("成熟植株"):uiText("收穫物"));const count=document.createElement('strong');count.className='quantity';count.textContent='× '+group.count;const name=document.createElement('span');name.textContent=p.short||p.name;card.append(im,count,name);if(ready){const hint=document.createElement('small');hint.textContent=uiText("收穫果實");card.append(hint);card.onclick=()=>collect(group.indices);}target.append(card);}}

function tick(){sendBook('clock',{active:!!state.active,running:!!state.active&&state.active.since!==null,name:state.active?.name||'',clock:clock(elapsed(state.active))});$('clock').textContent=clock(elapsed(state.active));renderGrowth();}
function makePot(index,ready=false){const p=plantFor(index),el=document.createElement(ready?'button':'div');el.className='pot '+(ready?'ready':'');const im=document.createElement('img');im.src=sprite(p,ready?3:4,p.variant);im.alt=ready?uiText("成熟待揭曉的盆栽"):p.name;const b=document.createElement('b');b.textContent=ready?uiText("成熟了 · 點我揭曉"):p.name;const small=document.createElement('small');small.textContent=ready?uiText("這盆已經長好了"):p.goal+uiText(" 分鐘的時光");el.append(im,b,small);if(ready)el.onclick=()=>collect([index]);return el;}
function renderLegacy(){$('legacyItems').replaceChildren();renderProduce($('legacyItems'),state.claimed);if(!state.claimed.length)empty($('legacyItems'),uiText("沒有舊作物收成。"));}
function empty(el,msg){const p=document.createElement('p');p.className='emptyMessage';p.textContent=msg;el.append(p);}
let gardenSignature='';
function renderGarden(){}
function renderCatalog(){}

function collect(ids,automatic=false){const g=growth(total(state));ids=ids.filter(i=>i<g.completed&&!state.claimed.includes(i));if(!ids.length)return;clearTimeout(matureTimeout);matureKey=-1;const p=plantFor(ids[0]);const settled=settleHarvest(state,ids,localDay());state.claimed=settled.claimed;state.harvests=settled.harvests;save();$('dropFruit').src=fruitSprite(p);$('dropFruit').classList.remove('dropping');void $('dropFruit').offsetWidth;$('dropFruit').classList.add('dropping');$('reveal').hidden=automatic;$('reveal').textContent=uiText("收穫 ")+ids.length+uiText(" 份，已加入今日結算；同類果實合併計數。");renderGarden();renderGrowth();renderBook();}

function addTime(minutes,source='manual'){if(source==='demo'){if(!state.active)state.active={id:uid(),taskId:null,name:uiText("快速體驗"),day:currentDay(),seconds:0,since:null,mushroomBase:0,source:'demo'};state.active.seconds=elapsed(state.active)+minutes*60;if(state.active.since!==null)state.active.since=Date.now();save();say(uiText("體驗時間已增加，按「結束並採收」揭曉小菇。"));renderTimer();renderTasks();tick();return;}const id=uid();state.sessions.push({id,name:$('manualName').value.trim()||uiText("補記時間"),day:currentDay(),seconds:minutes*60,ended:Date.now(),source});state.stump.pendingSeconds=(state.stump.pendingSeconds||0)+minutes*60;if($('manualHarvest').checked)state.stump=harvestMushrooms(state.stump,0,id,localDay());save();todaySignature='';say(uiText("已補記 ")+minutes+uiText(" 分鐘。")+($('manualHarvest').checked?uiText("小菇已採收。"):uiText("小菇繼續留在樹樁上。")));tick();renderBook();}

function range(){const d=new Date(($('bookDay').value||localDay())+'T12:00:00'),period=$('period').value;let begin=new Date(d),end=new Date(d);if(period==='week'){begin.setDate(d.getDate()-(d.getDay()+6)%7);end=new Date(begin);end.setDate(begin.getDate()+6);}if(period==='month'){begin=new Date(d.getFullYear(),d.getMonth(),1,12);end=new Date(d.getFullYear(),d.getMonth()+1,0,12);}return{begin:localDay(begin),end:localDay(end),title:period==='month'?(language==='en'?d.toLocaleDateString('en-US',{month:'long',year:'numeric'})+' · Mushroom harvest':d.getFullYear()+uiText(" 年 ")+(d.getMonth()+1)+uiText(" 月的蘑菇收成")):period==='week'?localDay(begin)+' — '+localDay(end):localDay(d)};}
function bookData(){const r=range(),sessions=state.sessions.filter(s=>s.day>=r.begin&&s.day<=r.end),batches=state.stump.harvests.filter(h=>h.day>=r.begin&&h.day<=r.end);return {...r,sessions,batches,count:batches.reduce((n,b)=>n+b.count,0),seconds:sessions.reduce((n,s)=>n+s.seconds,0)};}
function renderBook(){const b=bookData();renderWeekly();renderCatalog();$('bookTitle').textContent=b.title;renderReceipt(b);$('statTime').textContent=mins(b.seconds);$('statPlants').textContent=b.count+uiText(" 朵");$('statSessions').textContent=b.sessions.length+uiText(" 次");$('bookPlants').replaceChildren();renderMushrooms($('bookPlants'),b.batches);if(!b.count)empty($('bookPlants'),uiText("目前尚未有採收紀錄。"));}

function renderReceipt(b){const week=$('period').value==='week';$('settlement').classList.toggle('weekSettlement',week);const month=$('period').value==='month';$('receiptHeading').textContent=month?uiText("本月收成結算"):week?uiText("本週收成回顧"):uiText("今日收成結算");$('receiptLogo').src=receiptLogo(month?'month':'day');$('receiptLogo').alt=month?uiText("本月收成結算"):uiText("今日收成結算");$('receiptActivities').hidden=week;$('receiptActivities').replaceChildren();$('receiptNumber').textContent='HARVEST · '+b.begin.replaceAll('-','')+' · '+String(b.sessions.length).padStart(3,'0');for(const activity of activityRows(b.sessions,b.batches,state.sessions)){const row=document.createElement('div');row.className='receiptActivity';const image=document.createElement('img'),m=MUSHROOMS.find(m=>m.id===activity.icon);image.src=m?.src||'assets/mushrooms/mushroom-8.png';image.alt='';const text=document.createElement('div'),name=document.createElement('b'),meta=document.createElement('small'),duration=document.createElement('strong');name.textContent=activity.name;meta.textContent=activity.times+uiText(" 次記錄")+(activity.mushrooms?uiText(" · 採收 ")+activity.mushrooms+uiText(" 朵"):'');text.append(name,meta);duration.textContent=mins(activity.seconds);row.append(image,text,duration);$('receiptActivities').append(row);}if(!b.sessions.length)empty($('receiptActivities'),uiText("目前尚未有紀錄。"));}

function renderWeekly(){const isWeek=$('period').value==='week';$('weeklyReport').hidden=!isWeek;if(!isWeek)return;const b=range(),metric=$('weekMetric').value||'time',w=weekSummary(state,b.begin,metric),unit=metric==='time'?uiText("分鐘"):uiText("朵"),fmt=n=>Number(n.toFixed(1));$('weekTotal').textContent=metric==='time'?mins(w.total*60):fmt(w.total)+' '+unit;$('weekRange').textContent=b.begin+' — '+b.end;$('weekBars').replaceChildren();const max=Math.max(1,...w.current,...w.previous);[uiText("一"),uiText("二"),uiText("三"),uiText("四"),uiText("五"),uiText("六"),uiText("日")].forEach((label,i)=>{const col=document.createElement('div');col.className='weekColumn';const bars=document.createElement('div');bars.className='weekBarPair';for(const [v,type] of [[w.previous[i],'previous'],[w.current[i],'current']]){const bar=document.createElement('div');bar.className='weekBar '+type;bar.style.height=(v/max*100)+'%';bar.title=(type==='current'?uiText("本週"):uiText("前一週"))+uiText(" · 週")+label+' '+(metric==='time'?mins(v*60):fmt(v)+' '+unit);bar.setAttribute('aria-label',bar.title);bars.append(bar);}const value=document.createElement('small');value.className='dayValue';value.textContent=metric==='time'?(w.current[i]>=60?Math.floor(w.current[i]/60)+uiText("時")+Math.floor(w.current[i]%60)+uiText("分"):Math.floor(w.current[i])+uiText("分")):fmt(w.current[i]);const text=document.createElement('span');text.textContent=label;col.append(value,bars,text);$('weekBars').append(col);});const diff=w.total-w.previousTotal;$('weekComparison').textContent=uiText("前一週 ")+(metric==='time'?mins(w.previousTotal*60):fmt(w.previousTotal)+' '+unit)+' · '+(diff===0?uiText("和前一週相同"):(diff>0?uiText("多了 "):uiText("少了 "))+(metric==='time'?mins(Math.abs(diff)*60):fmt(Math.abs(diff))+' '+unit));}
async function exportImage(){
 if($('period').value!=='week')return exportReceipt();
 const button=$('exportPng');button.disabled=true;
 try{renderBook();const b=bookData(),canvas=await snapshotWeeklyReceipt($('settlement')),link=document.createElement('a');link.href=canvas.toDataURL('image/png');link.download=uiText("本週收成-")+b.begin+'.png';link.click()}
 catch(error){alert(error?.message||uiText("圖片匯出失敗，請稍後再試。"))}
 finally{button.disabled=false}
}

