function sendBook(type,payload={}){if(window.parent!==window)window.parent.postMessage({source:'daybook-mushrooms',type,...payload},location.origin);}
function syncBook(payload){const oldView=bookPayload?.view;bookPayload=payload;document.body.dataset.view=payload.view||'work';if(payload.view==='review'){$('bookTab').open=true;if(oldView!=='review')$('bookDay').value=payload.day;renderBook();}if(Array.isArray(payload.favorites))state.favorites=[...payload.favorites];state.tasks=payload.tasks.filter(t=>!t.deleted).map(t=>({id:t.id,text:t.text,kind:t.kind,day:t.date,done:[...t.done]}));$('taskDay').value=payload.day;$('linkedDay').textContent='· '+payload.day;document.body.dataset.night=payload.night?'true':'false';for(const [key,value] of Object.entries(payload.colors||{}))document.documentElement.style.setProperty(key,value);renderTasks();renderPicker();}
window.addEventListener('message',event=>{if(event.origin!==location.origin||event.source!==window.parent||event.data?.source!=='daybook-host')return;const payload=event.data;if(payload.type==='finish'){if(state.active)finish(!!state.active.taskId);return;}if(payload.type==='pause'){pauseResume();return;}if(payload.type==='start-task'){if(state.active){say(uiText("已有計時進行中，請先結束這次記錄。"));return;}if(state.tasks.some(t=>t.id===payload.id)){if(/^\d{4}-\d{2}-\d{2}$/.test(payload.day))$('taskDay').value=payload.day;start(payload.id);}return;}if(payload.type==='sync'&&Array.isArray(payload.tasks)&&/^\d{4}-\d{2}-\d{2}$/.test(payload.day))syncBook(payload);});
